                    if M is not None:
                        tx, ty = M[0, 2], M[1, 2]
                        scale = np.sqrt(M[0, 0]**2 + M[0, 1]**2)
                        angle = np.arctan2(M[1, 0], M[0, 0])

                        if tx > 2.0: labels.append("Pan Left")
